//
// Writes src/api-surface.ts: the entry point ts-json-schema-generator reads.
//
// Why a generated file rather than a one-line `export type * from '…/models'`:
// with `--type "*"` the generator silently drops ~57 of walletkit's exported
// types (TONTransferRequest, JettonsResponse, ConnectionRequestEvent,
// TONConnectSession, PreparedSignData, …) — i.e. most of the request/response
// shapes the wallet API is made of. Naming a type explicitly always works, so
// the surface declares one interface member per exported name, and `--expose all`
// then emits a definition for each. The list is read from walletkit's own barrel,
// so upstream additions are picked up automatically.
import fs from 'node:fs';
import path from 'node:path';

const BARREL = path.resolve('../../js/node_modules/@ton/walletkit/dist/esm/api/models/index.d.ts');
const OUT = path.resolve('src/api-surface.ts');

// Types that cannot be referenced as a plain type reference. Generics need
// arguments, and a few names are value-only exports.
const SKIP = new Set([
    // Result<T> is generic; its error half (ResultError) is exported separately.
    'Result',
    // A const object, not a type — its value type is exported as UnstakeModes.
    'UnstakeMode',
    // `'ton' | UserFriendlyAddress`, i.e. a string. openapi-generator turns that
    // anyOf into a class with two parameters both named `string`, which does not
    // compile. Nothing else references it, and callers just pass the address.
    'TokenAddress',
]);

const names = [];
const visited = new Set();

function add(name) {
    if (!SKIP.has(name) && !names.includes(name)) {
        names.push(name);
    }
}

/** Collects the type names a module exports, following re-exports. */
function collect(file) {
    if (visited.has(file) || !fs.existsSync(file)) return;
    visited.add(file);

    const source = fs.readFileSync(file, 'utf8');

    // `export type { A, B as C } from '…'` and `export { D } from '…'`.
    for (const match of source.matchAll(/export\s+(?:type\s+)?\{([^}]*)\}\s*from/g)) {
        for (const entry of match[1].split(',')) {
            const trimmed = entry.trim();
            if (trimmed) add(trimmed.split(/\s+as\s+/).pop().trim());
        }
    }

    // `export * from './x'` — the barrel uses these too, and they carry types
    // that exist nowhere else (TransactionTrace, TransactionPreviewOptions, …).
    for (const match of source.matchAll(/export\s+\*\s*from\s*'([^']+)'/g)) {
        collect(path.resolve(path.dirname(file), `${match[1]}.d.ts`));
    }

    // Declarations in this module itself, reached through a star re-export.
    // Deliberately not `export declare const`: those are values, not types.
    for (const match of source.matchAll(/export\s+(?:declare\s+)?(?:interface|type|enum)\s+(\w+)/g)) {
        add(match[1]);
    }
}

collect(BARREL);

names.sort();

const lines = [
    '// AUTO-GENERATED by build-surface.mjs — do not edit.',
    '//',
    '// One member per type exported from walletkit\'s api/models barrel. Naming each',
    '// type is what makes the generator emit it; `--type "*"` alone misses many.',
    '',
    'import type {',
    ...names.map((name) => `    ${name},`),
    "} from '@ton/walletkit/dist/esm/api/models/index';",
    '',
    '/** The generated DTO surface. Only its members matter, never the wrapper. */',
    'export interface ApiSurface {',
    ...names.map((name) => `    ${name.charAt(0).toLowerCase()}${name.slice(1)}: ${name};`),
    '}',
    '',
];

fs.writeFileSync(OUT, lines.join('\n'));
console.log(`surface: ${names.length} types -> ${path.relative(process.cwd(), OUT)}`);
